<script setup lang="ts">
import { unwrap } from '~/api/client'; import { displayError } from '~/utils/errors'; import { formatRupiah } from '~/utils/format';
definePageMeta({middleware:'auth'}); const api=useMarketplaceApi(); const portal=usePortal(); const pending=ref(true); const error=ref<unknown>();
const metrics=reactive({products:0,rfq:0,orders:0,payable:0,blocked:0});
async function load(){pending.value=true;error.value=undefined;try{if(!portal.activeStore.value)await portal.loadStores();const id=portal.activeStore.value?.id;if(!id)return;const [products,rfq,orders,payables]=await Promise.all([api.GET('/vendor/stores/{storeId}/products',{params:{path:{storeId:id},query:{limit:100}},cache:'no-store'}).then(unwrap),api.GET('/vendor/stores/{storeId}/quote-requests',{params:{path:{storeId:id},query:{limit:100}},cache:'no-store'}).then(unwrap),api.GET('/vendor/stores/{storeId}/orders',{params:{path:{storeId:id},query:{limit:100}},cache:'no-store'}).then(unwrap),api.GET('/vendor/stores/{storeId}/payables',{params:{path:{storeId:id},query:{limit:100}},cache:'no-store'}).then(unwrap)]);metrics.products=products.items.length;metrics.rfq=rfq.items.filter(x=>['SUBMITTED','OFFERED'].includes(x.status)).length;metrics.orders=orders.items.filter(x=>!['COMPLETED','CANCELLED'].includes(x.fulfillment_status)).length;metrics.payable=payables.items.reduce((sum:any,x:any)=>sum+Number(x.accrued_amount??0)+Number(x.adjustment_amount??0)-Number(x.paid_amount??0),0);metrics.blocked=payables.items.filter((x:any)=>x.eligibility==='BLOCKED').length;}catch(cause){error.value=cause;}finally{pending.value=false;}}
watch(()=>portal.storeId.value,()=>{void load();});onMounted(()=>{void load();});useSeoMeta({title:'Dashboard vendor — Niaga'});
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="vendor"/><div class="section-heading"><div><p class="eyebrow">Portal vendor</p><h1>Dashboard toko</h1></div><StoreSwitcher/></div><ApiState :pending="pending" :error="error?displayError(error):null" :empty="!pending&&!portal.activeStore.value" empty-title="Belum ada toko" empty-message="Selesaikan onboarding untuk mulai berjualan." @retry="load"><template #action><NuxtLink class="button" to="/vendor/onboarding">Mulai onboarding</NuxtLink></template><div class="metric-grid"><NuxtLink class="surface metric" to="/vendor/produk"><strong>{{ metrics.products }}</strong><span>Produk</span></NuxtLink><NuxtLink class="surface metric" to="/vendor/rfq"><strong>{{ metrics.rfq }}</strong><span>RFQ perlu respons</span></NuxtLink><NuxtLink class="surface metric" to="/vendor/pesanan"><strong>{{ metrics.orders }}</strong><span>Pesanan aktif</span></NuxtLink><NuxtLink class="surface metric" to="/vendor/keuangan"><strong>{{ formatRupiah(metrics.payable) }}</strong><span>Hak penerimaan</span><small>{{ metrics.blocked }} tertahan</small></NuxtLink></div><section class="surface section"><h2>Checklist toko</h2><ul class="check-list"><li>Profil dan alamat asal: <strong>{{ portal.activeStore.value?.status }}</strong></li><li>RFQ baru diperiksa sebelum masa respons habis.</li><li>Pesanan dibukukan untuk pengiriman hanya setelah pembayaran terverifikasi.</li><li>Payable tertahan sampai pemenuhan dan dispute selesai.</li></ul></section></ApiState></main></template>
